package core

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/tedkulp/drops/internal/model"
)

// BlockedIssue pairs one candidate with its still-open blockers.
type BlockedIssue struct {
	Issue     model.Issue `json:"issue"`
	BlockedBy []model.ID  `json:"blocked_by"`
}

// Ready returns the live, non-deferred Issues with no open blocks edge, over
// the candidate set filter names. An unset filter.Statuses means the actionable
// statuses, open and in_progress, so a caller that does not ask about status
// gets everything it could pick up rather than only what nobody has started.
func (core *Core) Ready(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
	limit := filter.Limit
	candidates, err := core.candidates(ctx, filter)
	if err != nil {
		return nil, err
	}
	blockers, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	now := core.currentTime()
	ready := make([]model.Issue, 0, len(candidates))
	for _, issue := range candidates {
		if deferred(issue, now) || len(blockers[issue.ID]) != 0 {
			continue
		}
		ready = append(ready, issue)
		if limit > 0 && len(ready) == limit {
			break
		}
	}
	return ready, nil
}

// Blocked returns the exact complement of Ready over the same live,
// non-deferred candidates, and reads filter.Statuses the same way. So the two
// partition one set between them: every actionable Issue is in exactly one.
func (core *Core) Blocked(ctx context.Context, filter IssueFilter) ([]BlockedIssue, error) {
	limit := filter.Limit
	candidates, err := core.candidates(ctx, filter)
	if err != nil {
		return nil, err
	}
	blockers, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	now := core.currentTime()
	blocked := make([]BlockedIssue, 0)
	for _, issue := range candidates {
		if deferred(issue, now) || len(blockers[issue.ID]) == 0 {
			continue
		}
		blocked = append(blocked, BlockedIssue{Issue: issue, BlockedBy: append([]model.ID(nil), blockers[issue.ID]...)})
		if limit > 0 && len(blocked) == limit {
			break
		}
	}
	return blocked, nil
}

// candidates is the row set Ready and Blocked partition: the Issues the filter
// names, unlimited so the limit applies to the answer rather than to the pool.
// The default lives here, once, so the two verbs cannot disagree about what an
// unstated status means.
//
// That default is `list`'s: open AND in_progress. Open alone left the Issue you
// had started in neither answer — `ready` could not offer you the work you were
// already doing, and `blocked` could not tell you what it was waiting on — so
// the two verbs summed to less than the live set they claim to partition
// (8bbam). Closed stays out: a finished Issue is neither actionable nor stuck.
func (core *Core) candidates(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
	if len(filter.Statuses) == 0 {
		filter.Statuses = []model.Status{model.StatusOpen, model.StatusInProgress}
	}
	filter.Limit = 0
	return core.store.Issues(ctx, filter)
}

// OpenBlockers maps each live, non-terminal Issue that still has an unfinished
// blocker to that Issue's open blocker ids, ascending. An Issue with no open
// blocker is absent rather than present and empty, so len(map[id]) is the
// blocked-by count for any id at all.
//
// It spans the whole store in one pair of reads and takes no filter, which is
// deliberate on both counts. A pane annotating a row set needs one call per
// refresh, never one per row; and a blocker outside the caller's scope still
// blocks, so a scoped map would under-report. The cost is therefore the whole
// store's, not the scope's: two reads and 4.9ms, best of 20, over the
// 1025-issue corpus, which keys 13 Issues (measured for qy3de.8).
func (core *Core) OpenBlockers(ctx context.Context) (map[model.ID][]model.ID, error) {
	issues, err := core.store.Issues(ctx, IssueFilter{IncludeTombstoned: true})
	if err != nil {
		return nil, err
	}
	terminal := make(map[model.ID]bool, len(issues))
	for _, issue := range issues {
		terminal[issue.ID] = issue.Tombstone == model.Tombstoned || issue.Status == model.StatusClosed
	}
	dependencies, err := core.store.Dependencies(ctx)
	if err != nil {
		return nil, err
	}
	blockers := make(map[model.ID][]model.ID)
	for _, dependency := range dependencies {
		if dependency.Tombstone == model.Tombstoned || dependency.Type != model.DepBlocks {
			continue
		}

package tui

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/tedkulp/drops/internal/core"
	"github.com/tedkulp/drops/internal/model"
	"github.com/tedkulp/drops/internal/store"
)

// Every test in this package runs against real temp SQLite. AGENTS.md is
// explicit that the datastore is not a discovered fact and gets no interface;
// what IS a discovered fact here — terminal size — arrives as a message, and
// the frame tests pin it with tea.WithWindowSize or by setting it directly.

type fixedClock struct{ now time.Time }

func (clock fixedClock) Now() time.Time { return clock.now }

// namedIDs hands out the ids a fixture asks for, in order, so a test that
// cares what an id looks like can say so; everything after them is a short
// deterministic id, because a random one would make a frame unrepeatable.
type namedIDs struct {
	values []model.ID
	minted int
}

func (source *namedIDs) NewID(_ model.OwnerKind, _ *model.ID, _ []model.ID) (model.ID, error) {
	if len(source.values) > 0 {
		id := source.values[0]
		source.values = source.values[1:]
		return id, nil
	}
	source.minted++
	return model.ID(fmt.Sprintf("iss%02d", source.minted)), nil
}

// fixture is one temp store, its core, the project the pane is scoped to, and
// the two seams the write set spends: the channel core's warning sink is
// pointed at, and the argv that stands in for $EDITOR.
type fixture struct {
	t        *testing.T
	core     *core.Core
	project  model.Project
	opened   *store.Store
	other    model.Project
	warnings chan core.Warning
	editor   []string
}

func newFixture(t *testing.T, ids ...model.ID) *fixture {
	t.Helper()
	opened, err := store.Open(t.Context(), filepath.Join(t.TempDir(), "drops.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { _ = opened.Close() })
	replica, err := model.ParseReplicaKey("aaaaaaaaaaaaaaaaaaaaaaaaae")
	if err != nil {
		t.Fatalf("parse replica: %v", err)
	}
	// The warning sink is wired the way cli wires it for `tui`: onto a
	// buffered channel the pane drains, because under an alt screen the
	// default stderr sink is invisible (qy3de.7 §5).
	warnings := make(chan core.Warning, 32)
	rules := core.New(opened, replica,
		fixedClock{now: time.Date(2026, 9, 4, 12, 0, 0, 0, time.UTC)},
		&namedIDs{values: ids},
		func(w core.Warning) { warnings <- w })

	project, err := rules.CreateProject(t.Context(), "drops")
	if err != nil {
		t.Fatalf("create project: %v", err)
	}
	other, err := rules.CreateProject(t.Context(), "beacon")
	if err != nil {
		t.Fatalf("create project: %v", err)
	}
	return &fixture{
		t: t, core: rules, opened: opened, project: project, other: other, warnings: warnings,
		// The default editor writes nothing and exits 0, which is the
		// silent-abort case. A test that wants text says so with editorWrites.
		editor: shEditor(":"),
	}
}

// shEditor is an $EDITOR made of a shell script. The path drops arrives at is
// "$1", because exec.Command's argument after -c becomes the shell's $0.
//
// A real process rather than a fake: AGENTS.md keeps real subsystems real, and
// the whole question these tests answer is what an editor's file and exit code
// do to the store.
func shEditor(script string) []string { return []string{"sh", "-c", script, "sh"} }

// editorWrites is an $EDITOR that puts body in the file and exits 0.
func editorWrites(body string) []string {
	return shEditor("printf %s " + shellQuote(body) + ` > "$1"`)
}

// shellQuote wraps a string in single quotes for the script above.
func shellQuote(text string) string {
	return "'" + strings.ReplaceAll(text, "'", `'\''`) + "'"
}

// issue writes one issue into the pane's own project.
func (f *fixture) issue(title string, priority int) model.Issue {
	f.t.Helper()
	return f.issueIn(f.project, title, priority)
}

// issueWith writes an issue carrying a body, which is how a test reaches the
// lines render.Console.Page deliberately does not reflow.
func (f *fixture) issueWith(title, description string, priority int) model.Issue {
	f.t.Helper()
	created, err := f.core.CreateIssue(f.t.Context(), core.CreateIssue{
		Project:     f.project.Key,
		Title:       title,
		Description: description,
		Type:        model.TypeTask,
		Priority:    priority,
	})
	if err != nil {
		f.t.Fatalf("create issue %q: %v", title, err)
	}
	return created
}

func (f *fixture) issueIn(project model.Project, title string, priority int) model.Issue {
	f.t.Helper()
	created, err := f.core.CreateIssue(f.t.Context(), core.CreateIssue{
		Project:  project.Key,
		Title:    title,
		Type:     model.TypeTask,
		Priority: priority,
	})
	if err != nil {
		f.t.Fatalf("create issue %q: %v", title, err)
	}
	return created
}

func (f *fixture) setStatus(id model.ID, status model.Status) {
	f.t.Helper()
	if _, err := f.core.SetIssueStatus(f.t.Context(), id, status, ""); err != nil {
		f.t.Fatalf("set status of %s: %v", id, err)
	}
}

// child writes an issue under a parent, which is how a fixture reaches the
// picker's Children group and its auto-sized id column.
func (f *fixture) child(parent model.ID, title string, priority int) model.Issue {
	f.t.Helper()
	created, err := f.core.CreateIssue(f.t.Context(), core.CreateIssue{
		Project:  f.project.Key,
		Parent:   &parent,
		Title:    title,
		Type:     model.TypeTask,
		Priority: priority,
	})
	if err != nil {
		f.t.Fatalf("create child of %s: %v", parent, err)
	}
	return created
}

// dep records one typed edge, from the issue that depends on the issue at to.
// The asymmetric titles in picker fixtures make a swapped direction visible.
func (f *fixture) dep(from, to model.ID, kind model.DependencyType) {
	f.t.Helper()
	if _, err := f.core.SetDependency(f.t.Context(), from, to, kind, true); err != nil {
		f.t.Fatalf("dep %s -%s-> %s: %v", from, kind, to, err)
	}
}

// reciprocal writes BOTH stored spellings of one `related` edge straight to
// the store, each authored by a different replica. core refuses to write the
// second one, so this is the only way the pair arrives: two machines each
// related the pair from their own end and sync merged two records that share
// no primary key (y7f6z).
func (f *fixture) reciprocal(first, second model.ID) {
	f.t.Helper()
	keys := []string{"aaaaaaaaaaaaaaaaaaaaaaaaae", "bbbbbbbbbbbbbbbbbbbbbbbbbe"}
	edges := [][2]model.ID{{first, second}, {second, first}}
	err := f.opened.WithTx(f.t.Context(), func(ctx context.Context, tx *store.Tx) error {
		for index, edge := range edges {
			replica, err := model.ParseReplicaKey(keys[index])
			if err != nil {
				return err
			}
			revision, err := model.InitialRevision(replica)
			if err != nil {
				return err
			}
			if err := tx.PutDependency(ctx, model.Dependency{
				FromID: edge[0], ToID: edge[1], Type: model.DepRelated,
				CreatedAt: "2026-09-04T12:00:00Z", Revision: revision,
			}); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		f.t.Fatalf("write a reciprocal pair: %v", err)
	}
}

// blocks records that blocked depends on blocker, which is what puts the
// ` [N]` marker on blocked's row.
func (f *fixture) blocks(blocked, blocker model.ID) {
	f.t.Helper()
	if _, err := f.core.SetDependency(f.t.Context(), blocked, blocker, model.DepBlocks, true); err != nil {
		f.t.Fatalf("dep %s -> %s: %v", blocked, blocker, err)
	}
}

// tombstone deletes an issue, which is how a fixture reaches the one state
// the modal offers no rows for. It stays reachable by following.
func (f *fixture) tombstone(id model.ID) {
	f.t.Helper()
	if _, err := f.core.SetIssueTombstone(f.t.Context(), id, model.Tombstoned); err != nil {
		f.t.Fatalf("tombstone %s: %v", id, err)
	}
}

// claim assigns an issue from outside the pane, which is both a fixture state
// and the race qy3de.7 §10 names: a claim landing between the render and the
// `enter`.
func (f *fixture) claim(id model.ID, who string) {
	f.t.Helper()
	if _, err := f.core.ClaimIssue(f.t.Context(), id, who); err != nil {
		f.t.Fatalf("claim %s: %v", id, err)
	}
}

// close closes an issue with a reason from outside the pane, which is how a
// fixture reaches the state `reopen` is offered from.
func (f *fixture) close(id model.ID, reason string) {
	f.t.Helper()
	if _, err := f.core.SetIssueStatus(f.t.Context(), id, model.StatusClosed, reason); err != nil {
		f.t.Fatalf("close %s: %v", id, err)
	}
}

// reread reads one issue back out of the store, which is how a write is
// asserted: through core, never through the pane's own copy.
func (f *fixture) reread(id model.ID) model.Issue {
	f.t.Helper()
	issue, err := f.core.ViewIssue(f.t.Context(), id)
	if err != nil {
		f.t.Fatalf("reread %s: %v", id, err)
	}
	return issue.Issue
}

// comments reads one issue's thread back out of the store.
func (f *fixture) comments(id model.ID) []model.Comment {
	f.t.Helper()
	issue, err := f.core.ViewIssue(f.t.Context(), id)
	if err != nil {
		f.t.Fatalf("reread %s: %v", id, err)
	}
	return issue.Comments
}

// model builds the navigator over this fixture, sized and loaded, exactly as
// Run would have left it before the program started.
func (f *fixture) model(width, height int) *Model {
	f.t.Helper()
	pane := New(f.core, f.project, "tester", f.editor, f.warnings)
	pane.ctx = f.t.Context()
	pane.width, pane.height = width, height
	pane.resize()
	if err := pane.reload(); err != nil {
		f.t.Fatalf("reload: %v", err)
	}
	return pane
}
package tui

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"strconv"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
)

// A frame test is REGRESSION COVER, not a control (map Notes): it fails on any
// byte that moves, so it proves nothing about a specific clause. What it does
// prove is the one thing a two-pane frame can silently get wrong — that every
// finished line is exactly as wide as the terminal, at every width, in every
// mode — which is how euv2e.4's two traps showed up as ragged panes.

// wideRow is a markdown table row. render.WrapText emits one untouched, on
// purpose, so this is how a page comes to hold a line far wider than the pane
// it was rendered for.
const wideRow = "| a path that goes on and on | a rate per gigabyte | a reason this row is far too wide for any pane the split gives it |"

// corpus is a fixture holding one of each thing the layout has to survive.
func corpus(t *testing.T) *fixture {
	t.Helper()
	f := newFixture(t, "beacon-responsive-layout-pass-6w0g", "iss01", "iss02", "iss03")
	// P0 so it leads the queue: the pane never re-sorts, and the CLI's order
	// is priority ascending, then newest first, then id.
	f.issueWith("The longest open id in the corpus, cut to twelve columns on its row",
		"## A table\n\n"+wideRow+"\n\nAnd a paragraph after it that wraps normally.", 0)
	blocked := f.issue("A blocked issue whose title has to survive the marker", 1)
	blocker := f.issue("The blocker", 2)
	f.blocks(blocked.ID, blocker.ID)
	f.issueIn(f.other, "Another project's issue", 3)
	return f
}

// frameModes is every mode the layout has to hold in, applied to a freshly
// loaded pane.
func frameModes(t *testing.T) []struct {
	name  string
	setup func(*Model)
} {
	t.Helper()
	return []struct {
		name  string
		setup func(*Model)
	}{
		{"at rest", func(*Model) {}},
		{"all projects", func(pane *Model) { press(t, pane, "a") }},
		{"closed included", func(pane *Model) { press(t, pane, "C") }},
		{"filtered", func(pane *Model) { pane.filter = "blocked"; _ = pane.applyFilter() }},
		{"no rows match", func(pane *Model) { pane.filter = "zzzz"; _ = pane.applyFilter() }},
		{"zoomed", func(pane *Model) { press(t, pane, "enter") }},
		{"soft-wrapped", func(pane *Model) { press(t, pane, "w") }},
		{"scrolled right", func(pane *Model) {
			for range 6 {
				press(t, pane, "l")
			}
		}},
		{"help", func(pane *Model) { press(t, pane, "?") }},
		// The picker replaces the detail pane's BODY, keeping the box and
		// its border title, so every frame law has to hold with one open.
		{"picker open", func(pane *Model) { openOnTheBlockedRow(t, pane) }},
		{"followed", func(pane *Model) {
			openOnTheBlockedRow(t, pane)
			pressNamed(t, pane, tea.KeyEnter)
			if len(pane.stack) != 1 {
				t.Fatalf("enter followed nothing; the depth line is not in this frame")
			}
		}},
		// qy3de.7's three additions: the same picker under two more titles,
		// and the message line, which is the one thing on this map that
		// changes how many rows the panes get.
		{"actions modal", func(pane *Model) { openActionsOn(t, pane) }},
		{"priority modal", func(pane *Model) {
			openActionsOn(t, pane)
			chooseRow(t, pane, "priority")
			if pane.kind != modalPriority {
				t.Fatal("the priority step did not open; this mode proves nothing")
			}
		}},
		{"prompt up", func(pane *Model) {
			press(t, pane, "C")
			pane.askToReopen(pane.detailID)
		}},
		{"message up", func(pane *Model) {
			pane.message = "AWS access key id matched in issue " + string(pane.detailID) + " (description)"
		}},
		{"a message far wider than the frame", func(pane *Model) {
			pane.message = strings.Repeat("a very long failure ", 20)
		}},
	}
}

// openOnTheBlockedRow moves to the corpus's one issue with a relation and
// opens the picker on it. `f` on an issue with none is a no-op, which would
// make a frame mode prove nothing.
func openOnTheBlockedRow(t *testing.T, pane *Model) {
	t.Helper()
	press(t, pane, "j")
	press(t, pane, "f")
	if pane.modal == nil {
		t.Fatalf("f opened no picker on %s; this mode proves nothing", pane.detailID)
	}
}

// assertSquare is the whole assertion a frame test makes.
func assertSquare(t *testing.T, what, block string, width, height int) {
	t.Helper()
	lines := strings.Split(block, "\n")
	if len(lines) != height {
		t.Errorf("%s: block is %d lines, want %d", what, len(lines), height)
	}
	for index, line := range lines {
		if got := lipgloss.Width(line); got != width {
			t.Errorf("%s: line %d measures %d columns, want %d: %q", what, index, got, width, line)
		}
	}
}

func TestEveryFrameLineMeasuresTheFrameWidth(t *testing.T) {
	fixture := corpus(t)

	for _, size := range []struct{ width, height int }{{80, 24}, {120, 40}, {60, 12}, {40, 3}} {
		for _, mode := range frameModes(t) {
			pane := fixture.model(size.width, size.height)
			mode.setup(pane)
			assertSquare(t, fmt.Sprintf("%dx%d %s", size.width, size.height, mode.name),
				pane.frame(), size.width, size.height)
		}
	}
}

// TestTheComposedFrameIsSquareBeforeItIsPadded is what stops frame's guard
	Clause  string `json:"clause"`
	File    string `json:"file"` // repo-relative
	Test    string `json:"test"` // as `go test -run` names it, subtests included
	Old     string `json:"old"`
	New     string `json:"new"`
	Package string `json:"package,omitempty"` // defaults to the file's own directory
}

// pkg is the package whose tests prove this control. It is derived from the
// file by default, so a control cannot name a file in one package and quietly
// run another's suite; the override exists for the case where a seam is proved
// from the package above it.
func (c Control) pkg() string {
	if c.Package != "" {
		return c.Package
	}
	return "./" + path.Dir(filepath.ToSlash(c.File))
}

// Catalogue is one package's controls.
type Catalogue struct {
	Note     string    `json:"note"`
	Controls []Control `json:"controls"`
}

// loadCatalogue decodes and validates one catalogue. Validation is total: a
// catalogue that loads is one every control in which can be run and recorded.
func loadCatalogue(path string, r io.Reader) (Catalogue, error) {
	var cat Catalogue
	if err := json.UnmarshalRead(r, &cat); err != nil {
		return Catalogue{}, fmt.Errorf("%s: %w", path, err)
	}
	seen := map[string]bool{}
	for i, c := range cat.Controls {
		where := fmt.Sprintf("%s: control %d", path, i)
		if c.Name != "" {
			where = fmt.Sprintf("%s: %s", path, c.Name)
		}
		for _, f := range []struct{ name, value string }{
			{"control", c.Name}, {"clause", c.Clause}, {"file", c.File},
			{"test", c.Test}, {"old", c.Old},
		} {
			if strings.TrimSpace(f.value) == "" {
				return Catalogue{}, fmt.Errorf("%s: %s is missing", where, f.name)
			}
		}
		if c.Old == c.New {
